rules.formula:
AND(
  Armor_dollars__c >= 50000,
  OR(
    ISPICKVAL(Type__c, "Quote"),
    ISPICKVAL(Type__c, "Order")
  ),
  OR(
    NOT(ISPICKVAL(Status__c, "Closed")),
    NOT(ISPICKVAL(Status__c, "Cancelled"))
  ),
  OR(
    /* 1. New record that qualifies */
    ISNEW(), 	
    /* 2. Record was previously unqualified, now qualifies */    
    AND(
      ISCHANGED(Armor_dollars__c),
      PRIORVALUE(Armor_dollars__c) < 50000
    ), 
    /* 3. Qualified Quote changes to Order */
    AND(
      ISCHANGED(Type__c),
      ISPICKVAL(Type__c, "Order"),
      ISPICKVAL(PRIORVALUE(Type__c), "Quote")
    ) 
  )
)

/* 1. New record that qualifies */
OR( 

   AND(
      ISNEW(),
      Total_Order_Sales__c > 25000,
      OR(
        ISPICKVAL(Type__c, "Quote"),
        ISPICKVAL(Type__c, "Order")
        ),
      OR(
        Entered_By__r.UserRole.Name = "Inside Sales - CSC",
        Entered_By__c = "0050d000007BeYm"
        )
      ),

/* 2. Record was previously unqualified, now qualifies */
   AND(
      NOT(ISNEW()),
      Total_Order_Sales__c > 25000,
      OR(
        Entered_By__r.UserRole.Name = "Inside Sales - CSC",
        Entered_By__c = "0050d000007BeYm"
        ),
      OR(
        ISPICKVAL(Type__c, "Quote"),
        ISPICKVAL(Type__c, "Order")
        ),
      OR(
        AND(
           ISCHANGED(Total_Order_Sales__c),
           PRIORVALUE(Total_Order_Sales__c) <= 25000
           )
        )
      ),
/* 3. Qualified Quote changes to Order */
   AND(
      ISCHANGED(Type__c),
      ISPICKVAL(Type__c, "Order"),
      ISPICKVAL(PRIORVALUE(Type__c), "Quote"),
      Total_Order_Sales__c > 25000,
      OR(
        Entered_By__r.UserRole.Name = "Inside Sales - CSC",
        Entered_By__c = "0050d000007BeYm"
        )
      )
  )

AND(
  HT_Dollars__c >= 25000,
  OR(
    ISPICKVAL(Type__c, "Quote"),
    ISPICKVAL(Type__c, "Order")
  ),
  OR(
    NOT(ISPICKVAL(Status__c, "Closed")),
    NOT(ISPICKVAL(Status__c, "Cancelled"))
  ),
  OR(
    /* 1. New record that qualifies */
    ISNEW(),
    /* 2. Record was previously unqualified, now qualifies */
    AND(
      ISCHANGED(HT_Dollars__c),
      PRIORVALUE(HT_Dollars__c) < 25000
    ),
    /* 3. Qualified Quote changes to Order */
    AND(
      ISCHANGED(Type__c),
      ISPICKVAL(Type__c, "Order"),
      ISPICKVAL(PRIORVALUE(Type__c), "Quote")
    )
  )
)

AND(
  MV_dollars__c >= 5000,
  OR(
    ISPICKVAL(Type__c, "Quote"),
    ISPICKVAL(Type__c, "Order")
  ),
  OR(
    NOT(ISPICKVAL(Status__c, "Closed")),
    NOT(ISPICKVAL(Status__c, "Cancelled"))
  ),
  OR(
    /* 1. New record that qualifies */
    ISNEW(),
    /* 2. Record was previously unqualified, now qualifies */
    AND(
      ISCHANGED(MV_dollars__c),
      PRIORVALUE(MV_dollars__c) < 5000
    ),
    /* 3. Qualified Quote changes to Order */
    AND(
      ISCHANGED(Type__c),
      ISPICKVAL(Type__c, "Order"),
      ISPICKVAL(PRIORVALUE(Type__c), "Quote")
    )
  )
)
